/// <summary>
/// NDX_MultipleS_QuotationRange_Item
/// </summary>
class NDX_MultipleS_QuotationRange_Item extends NDX_MultipleSelect_QuotationRange
{
    InventTable inventTable;

}

Method.Source:
protected void new(InventTable _inventTable, QuotationIdBase _quotationId = '')
{
    NDXMultipleS_SalesQuotationRange   nDX_MultipleS_QuotationRange;
    super();

    inventTable      = _inventTable;
    quotationId = _quotationId;

    itemValidityErrors.ValidityCheckType = NDXValidityCheckType::QuotationRange;
    itemValidityErrors.checkMessage      = strfmt("@NDX:NDXItemValidityQuotationRangeTest", quotationId);

    while select  nDX_MultipleS_QuotationRange
        where     nDX_MultipleS_QuotationRange.RefRecId_InventTable == inventTable.RecId
    {
        nDX_SelectionTmp.RangeQuotation = nDX_MultipleS_QuotationRange.RangeQuotation;
        nDX_SelectionTmp.doInsert();
    }
}

static public NDX_MultipleS_QuotationRange_Item construct(InventTable _inventTable, QuotationIdBase _quotationId = '')
{
    return new NDX_MultipleS_QuotationRange_Item(_inventTable, _quotationId);
}

/// <summary>
/// Constructor
/// </summary>
/// <param name = "obj">NDX_ItemValidity</param>
/// <param name = "quotationId">QuotationIdBase</param>
/// <returns>NDX_MultipleS_QuotationRange_Item object</returns>
static NDX_MultipleS_QuotationRange_Item new_FromNDX_ItemValidity(NDX_ItemValidity obj, QuotationIdBase quotationId)
{
    NDX_MultipleS_QuotationRange_Item      nDX_MultipleS_QuotationRange_Item;
    ;
    nDX_MultipleS_QuotationRange_Item = new NDX_MultipleS_QuotationRange_Item(obj.parmInventTable(), quotationId);
    nDX_MultipleS_QuotationRange_Item.parmOItemValidity(obj);
    return nDX_MultipleS_QuotationRange_Item;

}

/// <summary>
/// Checks if item is valid vor quotation range
/// </summary>
/// <returns>container</returns>
public container isValid()
{
    NDXValidityMessage validityMessage = '';
    boolean     lIsValid = true;
    ;
    // keine Gültigkeitsprüfung hinterlegt
    if (nDX_SelectionTmp.RecId == 0)
    {
        return [lIsValid, validityMessage];
    }

    select firstonly nDX_SelectionTmp where quotationId like nDX_SelectionTmp.RangeQuotation;

    if (nDX_SelectionTmp)
    {
        return [lIsValid, validityMessage];
    }

    lIsValid        = false;

    // Der Artikel darf nur in Angeboten mit dem Muster [%1] angeboten werden!
    validityMessage = strFmtLB(strfmt("@NDX:NDXItemValidityQuotationRange", NDXMultipleS_SalesQuotationRange::Range2String(InventTable.RecId)));

    itemValidityErrors.ErrorMessage = validityMessage;
    oItemValidity.addErrorMessage(itemValidityErrors);

    return [lIsValid, validityMessage];
}
